// Una "base" en memoria. Cada pedido de asignación hace: leer, chequear, escribir.
const base = { hoja: { id: 'HR-1', capacidadG: 1000000, paradas: [{ id: 'A', pesoG: 700000 }] } };
const leer = () => JSON.parse(JSON.stringify(base.hoja));

const sumaG = (h) => h.paradas.reduce((s, p) => s + p.pesoG, 0);

// Servicio que chequea la regla ANTES de escribir, pero fuera de toda frontera de consistencia.
function pasoLeer(parada) { return { parada, vista: leer() }; }
function pasoChequear(t) {
  if (sumaG(t.vista) + t.parada.pesoG > t.vista.capacidadG) throw new Error('No entra: ' + t.parada.id);
  return t;
}
// Escribir es un INSERT de la fila de la parada: cada pedido agrega la suya.
function pasoEscribir(t) { base.hoja.paradas.push(t.parada); }

// Dos pedidos llegan a la vez: se intercalan los pasos.
const t1 = pasoLeer({ id: 'B', pesoG: 200000 });
const t2 = pasoLeer({ id: 'C', pesoG: 250000 });
pasoChequear(t1);   // 700 + 200 = 900 <= 1000: pasa
pasoChequear(t2);   // 700 + 250 = 950 <= 1000: pasa (todavía ve el estado viejo)
pasoEscribir(t1);
pasoEscribir(t2);   // las dos filas quedan: 700 + 200 + 250
console.log('Paradas guardadas:', base.hoja.paradas.map((p) => p.id).join(', '));
console.log('Peso total:', sumaG(base.hoja) / 1000, 'kg de', base.hoja.capacidadG / 1000);

// Objeto de valor: el peso se guarda en gramos enteros y no se modifica nunca.
class Peso {
  #g;
  constructor(gramos) {
    if (!Number.isInteger(gramos) || gramos < 0) throw new Error('Peso inválido: ' + gramos);
    this.#g = gramos;
    Object.freeze(this);
  }
  static deKg(kg) { return new Peso(Math.round(kg * 1000)); }
  get gramos() { return this.#g; }
  mas(otro) { return new Peso(this.#g + otro.gramos); }
  noSuperaA(otro) { return this.#g <= otro.gramos; }
  igualA(otro) { return this.#g === otro.gramos; }
  toString() { return (this.#g / 1000).toFixed(3) + ' kg'; }
}

// El problema que evita: decimales flotantes.
console.log('Con flotantes: 0.1 + 0.2 =', 0.1 + 0.2, '| 1.1 + 2.2 =', 1.1 + 2.2);
const suma = Peso.deKg(1.1).mas(Peso.deKg(2.2));
console.log('Con Peso: 1,1 kg + 2,2 kg =', String(suma), '(' + suma.gramos + ' g)');

// Igualdad por valor, no por identidad.
console.log('Dos pesos de 2 kg, ¿iguales?', Peso.deKg(2).igualA(Peso.deKg(2)), '| con {kg:2} === {kg:2}:', ({ kg: 2 }) === ({ kg: 2 }));

try { new Peso(-5); } catch (e) { console.log('Error:', e.message); }

// ── Objetos de valor ──
class Peso {
  constructor(g) { if (!Number.isInteger(g) || g < 0) throw new Error('peso_invalido'); this.g = g; Object.freeze(this); }
  static deKg(kg) { return new Peso(Math.round(kg * 1000)); }
  mas(o) { return new Peso(this.g + o.g); }
  noSuperaA(o) { return this.g <= o.g; }
  toString() { return (this.g / 1000).toFixed(1) + ' kg'; }
}

// ── Agregado: HojaDeRuta es la raíz; las paradas solo se tocan a través de ella ──
class HojaDeRuta {
  #paradas; #eventos = [];
  constructor(id, capacidad, paradas = [], version = 0) {
    this.id = id; this.capacidad = capacidad; this.#paradas = paradas; this.version = version;
  }
  get pesoCargado() { return this.#paradas.reduce((s, p) => s.mas(p.peso), new Peso(0)); }
  get paradas() { return this.#paradas.map((p) => ({ ...p })); }
  // La invariante vive acá y solo acá: lo cargado nunca supera la capacidad.
  asignarParada(id, peso) {
    if (this.#paradas.some((p) => p.id === id)) throw new Error('parada_repetida');
    if (!this.pesoCargado.mas(peso).noSuperaA(this.capacidad)) throw new Error('no_entra');
    this.#paradas.push({ id, peso });
    this.#eventos.push({ tipo: 'ParadaAsignada', hoja: this.id, parada: id, pesoG: peso.g });
  }
  sacarEventos() { const e = this.#eventos; this.#eventos = []; return e; }
}

// ── Repositorio con control optimista de versión (como en Vernon 2011) ──
const tabla = new Map();
tabla.set('HR-1', { capG: 1000000, paradas: [{ id: 'A', g: 700000 }], version: 1 });
const repo = {
  cargar(id) {
    const r = tabla.get(id);
    return new HojaDeRuta(id, new Peso(r.capG), r.paradas.map((p) => ({ id: p.id, peso: new Peso(p.g) })), r.version);
  },
  guardar(h) {
    const r = tabla.get(h.id);
    if (r.version !== h.version) throw new Error('version_vieja');
    tabla.set(h.id, { capG: h.capacidad.g, paradas: h.paradas.map((p) => ({ id: p.id, g: p.peso.g })), version: r.version + 1 });
  },
};

const eventosPublicados = [];
function asignar(hoja, id, kg) {
  hoja.asignarParada(id, Peso.deKg(kg));
  repo.guardar(hoja);
  eventosPublicados.push(...hoja.sacarEventos());
}

// Los mismos dos pedidos simultáneos de antes: ambos leen la versión 1.
const h1 = repo.cargar('HR-1');
const h2 = repo.cargar('HR-1');
asignar(h1, 'B', 200);
console.log('B asignada. Cargado:', String(repo.cargar('HR-1').pesoCargado), '| versión', tabla.get('HR-1').version);
try { asignar(h2, 'C', 250); } catch (e) { console.log('C rechazada por:', e.message); }
// Se reintenta con una lectura nueva: ahora la regla del agregado decide.
const h3 = repo.cargar('HR-1');
try { asignar(h3, 'C', 250); } catch (e) { console.log('C reintentada, rechazada por:', e.message); }
asignar(repo.cargar('HR-1'), 'D', 50);
console.log('Cargado final:', String(repo.cargar('HR-1').pesoCargado), 'de 1000.0 kg');
console.log('Eventos:', JSON.stringify(eventosPublicados));

// Los eventos son hechos en pasado. Quien quiera enterarse, se suscribe; la hoja no sabe quién.
const oyentes = {
  ParadaAsignada: [
    (e) => console.log('→ avisar al cliente de la parada ' + e.parada),
    (e) => console.log('→ recalcular el recorrido de ' + e.hoja),
  ],
};
for (const e of eventosPublicados) for (const f of oyentes[e.tipo] ?? []) f(e);
